Definition rval (x : range_ans) : Z := match x with RgErr e => neg_errno e | RgDone _ => 0 end.

Lemma path_munmap : forall addr len s mo tr z s' mo',
  tpath stp (ev_step atop (EMunmap addr len) s) mo tr (Ok (z, s')) mo' <->
